import sys

class Node:
    def __init__(self, name, duration):
        self.name = name
        self.duration = duration
        self.prev = None
        self.next = None

def main():
    Q = int(sys.stdin.readline().strip())
    head = None
    tail = None
    current = None
    song_map = {}  # name -> node

    for _ in range(Q):
        line = sys.stdin.readline().strip()
        if not line:
            continue
        parts = line.split()
        op = parts[0].upper()

        if op == "ADD":
            name = parts[1]
            duration = int(parts[2])
            new_node = Node(name, duration)
            if head is None:
                head = new_node
                tail = new_node
                current = new_node
            else:
                tail.next = new_node
                new_node.prev = tail
                tail = new_node
            song_map[name] = new_node

        elif op == "DELETE":
            name = parts[1]
            if name not in song_map:
                print("Song not found")
            else:
                node = song_map[name]
                # Update current if needed
                if current == node:
                    current = node.next if node.next else node.prev

                # Remove from doubly linked list
                if node.prev:
                    node.prev.next = node.next
                else:
                    head = node.next

                if node.next:
                    node.next.prev = node.prev
                else:
                    tail = node.prev

                del song_map[name]

        elif op == "NEXT":
            if current is None or current.next is None:
                print("No next song")
            else:
                current = current.next

        elif op == "PREV":
            if current is None or current.prev is None:
                print("No previous song")
            else:
                current = current.prev

        elif op == "PRINT":
            if current is None:
                print()
            else:
                result = []
                node = current
                while node:
                    result.append(node.name)
                    node = node.next
                print(' '.join(result))

if __name__ == "__main__":
    main()
